const NEHRU_INFO={id:"jawaharlal-nehru",name:"Jawaharlal Nehru",title:"Architect of Modern India & Leader of Freedom Struggle",lifespan:"14 November 1889 – 27 May 1964",birthplace:"Allahabad (Prayagraj), United Provinces, British India",education:"Harrow School, Trinity College (Cambridge), Inner Temple (London)",roles:["First Prime Minister of Independent India (1947–1964)","President of Indian National Congress (1929, 1936, 1937, 1946, 1951–1954)","Key Leader of Non-Cooperation, Civil Disobedience & Quit India Movements","Co-Founder of Non-Aligned Movement (NAM)","Author of 'The Discovery of India' & 'Glimpses of World History'"],quickStats:[{label:"Prison Years",value:"9 Jail Terms (3,259 Days)",icon:"🏛️"},{label:"Purna Swaraj",value:"Lahore Congress 1929",icon:"🚩"},{label:"First Prime Minister",value:"1947 – 1964",icon:"🇮🇳"},{label:"Famous Speech",value:"Tryst with Destiny",icon:"🎙️"},{label:"Major Works",value:"Discovery of India",icon:"📖"},{label:"Bharat Ratna",value:"Awarded 1955",icon:"🎖️"}]},BIOGRAPHY_DATA={title:"Biography & Early Life",subtitle:"From Cambridge law scholar to the guiding light of Indian democracy.",paragraphs:["Jawaharlal Nehru was born on 14 November 1889 in Allahabad to Motilal Nehru, a wealthy barrister, and Swarup Rani. Raised in a privileged environment at Anand Bhavan, he received private tutoring before traveling to England in 1905 to study at Harrow School and Trinity College, Cambridge, where he earned an honors degree in Natural Science. He subsequently studied law at the Inner Temple and was called to the Bar in 1912.","Returning to India in 1912, Nehru joined the Allahabad High Court bar, but corporate legal practice held little interest for him. Deeply moved by the nationalist fervor sweeping the country, he attended the Bankipore Congress session in 1912 and joined Annie Besant's Home Rule League in 1916. That same year, at the Lucknow Congress, he met Mahatma Gandhi—a meeting that transformed his life and redirected his energies toward the freedom movement.","Under Gandhi's mentorship, Nehru immersed himself in agrarian struggles, leading the Pratapgarh peasant agitation in 1920. His passionate advocacy for anti-imperialism, secularism, and socialism earned him widespread support among young nationalists. Elected INC President at the historic 1929 Lahore Session, Nehru drafted the pledge of Purna Swaraj (Complete Independence), replacing Dominion status as the nation's goal.","Following Independence on 15 August 1947, Nehru served as India's first Prime Minister until his death in 1964. He championed parliamentary democracy, secularism, scientific temper, state-led industrial planning, established world-class educational institutions like IITs, AIIMS, and ISRO (INCOSPAR), and formulated India's non-aligned foreign policy."]},TIMELINE_DATA=[{year:"1889",title:"Born in Allahabad",description:"Jawaharlal Nehru was born on 14 November 1889 to Motilal Nehru and Swarup Rani in Allahabad."},{year:"1905–1912",title:"Education in England",description:"Studied at Harrow School, Trinity College Cambridge (Natural Sciences), and called to the Bar at Inner Temple, London."},{year:"1916",title:"First Meeting with Mahatma Gandhi",description:"Met Gandhi at the Lucknow Congress session; married Kamala Kaul on Vasanta Panchami."},{year:"1920",title:"Pratapgarh Peasant Movement & Non-Cooperation",description:"Led rural peasant marches in UP; joined Gandhi's Non-Cooperation Movement and was arrested for the first time in Dec 1921."},{year:"1927",title:"Brussels Conference & USSR Visit",description:"Attended the Congress of Oppressed Nationalities in Brussels and visited Moscow, shaping his socialist and anti-imperialist worldview."},{year:"1929",title:"Lahore Congress & Purna Swaraj Declaration",description:"Presided over the Lahore Session of Congress; raised the Indian tricolour on the Ravi riverbank at midnight, declaring Complete Independence."},{year:"1930–1934",title:"Salt Satyagraha & Mass Imprisonments",description:"Led salt satyagraha in UP; spent long jail terms writing 'Glimpses of World History' as letters to his daughter Indira."},{year:"1936–1937",title:"Re-elected Congress President & Election Campaign",description:"Elected Congress President at Lucknow (1936) and Faizpur (1937); spearheaded provincial election campaign across 11 provinces."},{year:"1942–1945",title:"Quit India Movement & Ahmednagar Fort Prison",description:"Moved the historic 'Quit India' resolution in Bombay; arrested on 9 August 1942 and jailed for 1,041 days at Ahmednagar Fort, writing 'The Discovery of India'."},{year:"1946",title:"Heading the Interim Government",description:"Sworn in as Vice-President of the Viceroy's Executive Council (De Facto Prime Minister) of the Interim Government of India."},{year:"1947",title:"Tryst with Destiny & Prime Ministership",description:"Delivered his immortal speech at midnight on 14-15 August 1947 and took oath as independent India's first Prime Minister."},{year:"1955",title:"Bandung Conference & Non-Aligned Movement",description:"Co-founded the Non-Aligned Movement (NAM) in Bandung, Indonesia; awarded the Bharat Ratna."},{year:"1964",title:"Passing Away",description:"Passed away in New Delhi on 27 May 1964 while serving as Prime Minister."}],MAJOR_MOVEMENTS_DATA=[{id:"kisan-movement",title:"Pratapgarh Kisan Agitation (1920)",icon:"🌾",subtitle:"Bridging the Congress with Agrarian India",description:"In 1920, Nehru spent weeks visiting villages in Oudh (Pratapgarh district), witnessing the extreme oppression of landless peasants by talukdars and British tax collectors. This experience grounded his national politics in rural economic reality."},{id:"non-cooperation",title:"Non-Cooperation Movement (1920–1922)",icon:"🕊️",subtitle:"First Mass Satyagraha & First Arrest",description:"Nehru enthusiastically organized the boycott of foreign cloth and British legal institutions in UP. In December 1921, he was arrested alongside his father Motilal Nehru—marking the beginning of his 9 jail incarcerations."},{id:"purna-swaraj",title:"Lahore Congress & Purna Swaraj (1929)",icon:"🚩",subtitle:"Declaring Complete Independence on the Ravi Riverbank",description:"At age 40, Nehru presided over the Lahore Congress session. He rejected Dominion status and hoisted the tricolour flag at midnight on 31 December 1929, designating 26 January 1930 as Independence Day."},{id:"salt-satyagraha",title:"Salt Satyagraha & Civil Disobedience (1930)",icon:"🧂",subtitle:"Mass Defiance of British Salt Monopolies",description:"Nehru organized mass salt manufacturing and picketings across Allahabad and UP. Arrested in April 1930, he served six months in Naini Jail, where he began writing historical essays for his daughter."},{id:"individual-satyagraha",title:"Individual Satyagraha (1940)",icon:"✊",subtitle:"Protesting Forced World War II Dragooning",description:"Selected by Mahatma Gandhi as the second Satyagrahi (after Acharya Vinoba Bhave), Nehru delivered anti-war speeches protesting Britain dragging India into WWII without consent, resulting in a 4-year sentence at Bareilly Jail."},{id:"quit-india",title:"Quit India Movement (1942)",icon:"🔥",subtitle:"'Do or Die' Resolution & Ahmednagar Incarceration",description:"Nehru drafted and moved the Quit India resolution at Gowalia Tank Maidan, Bombay on 8 August 1942. Arrested hours later, he was imprisoned at Ahmednagar Fort until June 1945."}],PRISON_YEARS_DATA={title:"Prison Years & Literary Masterpieces",subtitle:"Spending 3,259 days (nearly 9 years) in 9 jail terms, turning prison cells into halls of world literature.",intro:"Jawaharlal Nehru was incarcerated nine times by the British colonial administration between 1921 and 1945. Far from breaking his spirit, jail provided him with solitude to read deeply and write foundational works of Indian and world history.",books:[{title:"Glimpses of World History (1934)",writtenIn:"Naini, Bareilly & Dehradun Jails (1930–1933)",pages:"196 letters to his daughter Indira Gandhi",description:"A sweeping narrative of human civilization written from memory without reference books, exploring Asian, European, and African histories from ancient times to the modern era."},{title:"An Autobiography / Toward Freedom (1936)",writtenIn:"Almora & Dehradun Jails (1934–1935)",pages:"610 pages",description:"Written during his wife Kamala's severe illness, this candid introspection outlines his political philosophy, personal struggles, and vision for free India."},{title:"The Discovery of India (1946)",writtenIn:"Ahmednagar Fort Prison (1942–1945)",pages:"Written during 1,041 days of solitary confinement",description:"Nehru's magnum opus examining 5,000 years of Indian history, philosophy, art, and culture, articulating his concept of 'Unity in Diversity'."}],jailTerms:[{term:"1st Term",year:"Dec 1921 – Mar 1922",jail:"Lucknow District Jail"},{term:"2nd Term",year:"May 1922 – Jan 1923",jail:"Lucknow District Jail"},{term:"3rd Term",year:"Sep 1923 – Oct 1923",jail:"Nabha Princely State Jail"},{term:"4th Term",year:"Apr 1930 – Oct 1930",jail:"Naini Central Prison"},{term:"5th Term",year:"Oct 1930 – Jan 1931",jail:"Naini Central Prison"},{term:"6th Term",year:"Dec 1931 – Aug 1933",jail:"Bareilly & Dehradun Jails"},{term:"7th Term",year:"Feb 1934 – Sep 1935",jail:"Almora & Dehradun Jails"},{term:"8th Term",year:"Oct 1940 – Dec 1941",jail:"Dehradun & Bareilly Jails"},{term:"9th Term",year:"Aug 1942 – Jun 1945",jail:"Ahmednagar Fort & Almora Jail"}]},HISTORIC_SPEECHES_DATA=[{id:"tryst-with-destiny",title:"Tryst with Destiny",date:"14–15 August 1947",venue:"Constituent Assembly of India, New Delhi",excerpt:"Long years ago we made a tryst with destiny, and now the time comes when we shall redeem our pledge, not wholly or in full measure, but very substantially. At the stroke of the midnight hour, when the world sleeps, India will awake to life and freedom...",significance:"Delivered on the eve of Indian Independence; acclaimed globally as one of the greatest speeches of the 20th century."},{id:"light-has-gone-out",title:"The Light Has Gone Out of Our Lives",date:"30 January 1948",venue:"All India Radio Address, New Delhi",excerpt:"Friends and comrades, the light has gone out of our lives and there is darkness everywhere... Our beloved leader, Bapu as we called him, the Father of the Nation, is no more... The light that has illumined this country for these many many years will illumine this country for many more years...",significance:"Spontaneous national radio address following the assassination of Mahatma Gandhi, calling for unity, peace, and secular restraint."},{id:"purna-swaraj-speech",title:"Purna Swaraj Presidential Address",date:"29 December 1929",venue:"INC Session, Lahore (Ravi Riverbank)",excerpt:"I must frankly confess that I am a socialist and a republican, and am no believer in kings and princes, or in the order which produces the modern kings of industry... Greatness comes from vision, tolerance of spirit, compassion and an even temper...",significance:"Set the ultimate goal of the Indian freedom movement as total independence from British rule."},{id:"temples-of-modern-india",title:"Temples of Modern India Speech",date:"8 July 1954",venue:"Bhakra Nangal Dam Inauguration, Punjab",excerpt:"As I walked around the site I thought that these days the biggest temple and mosque and church is the place where man works for the good of mankind... Bhakra, the biggest dam in India, is a symbol of India's progress.",significance:"Defined Nehru's vision of science, technology, dams, and heavy industry as the bedrock of self-reliant nation-building."}],GALLERY_DATA=[{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7e/Jawaharlal_Nehru_1947.jpg/800px-Jawaharlal_Nehru_1947.jpg",caption:"Jawaharlal Nehru delivering his historic 'Tryst with Destiny' address on 14 August 1947.",category:"Independence & Speeches"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/Gandhi_and_Nehru_1942.jpg/800px-Gandhi_and_Nehru_1942.jpg",caption:"Mahatma Gandhi and Jawaharlal Nehru at the AICC meeting in Bombay during the Quit India resolution (July 1942).",category:"Freedom Struggle"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/3/36/Nehru_signing_the_constitution.jpg/800px-Nehru_signing_the_constitution.jpg",caption:"Jawaharlal Nehru signing the Constitution of India in the Constituent Assembly (January 1950).",category:"Nation Building"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/1/18/Jawaharlal_Nehru_and_Patel_1947.jpg/800px-Jawaharlal_Nehru_and_Patel_1947.jpg",caption:"Jawaharlal Nehru with Sardar Vallabhbhai Patel during the transfer of power (1947).",category:"Leadership"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Nehru_at_Bandung_Conference_1955.jpg/800px-Nehru_at_Bandung_Conference_1955.jpg",caption:"Nehru at the Asian-African Bandung Conference in Indonesia (1955), co-founding Non-Alignment.",category:"Global Statesmanship"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/2/29/Jawaharlal_Nehru_in_his_study.jpg/800px-Jawaharlal_Nehru_in_his_study.jpg",caption:"Jawaharlal Nehru in his study room at Teen Murti Bhavan, surrounded by books.",category:"Literary Life"}],REFERENCES_DATA=[{title:"Selected Works of Jawaharlal Nehru",type:"Primary Archival Series",description:"Multi-volume documentary publication by Jawaharlal Nehru Memorial Fund (JNMF) containing original letters, speeches, and manuscripts."},{title:"The Discovery of India (1946)",type:"Autobiographical Historical Work",description:"Nehru's masterwork written in Ahmednagar Fort jail, published by Oxford University Press."},{title:"Nehru: The Invention of India (Shashi Tharoor)",type:"Biographical Monograph",description:"Critical biography examining Nehru's role in creating India's secular democratic constitution and non-aligned foreign policy."},{title:"Prime Ministers' Museum & Library (PMML / NMML)",type:"National Archives & Museum",description:"Teen Murti Bhavan, New Delhi — repository of Nehru's personal papers, books, photographs, and official records."}];"undefined"!=typeof module&&module.exports&&(module.exports={NEHRU_INFO:NEHRU_INFO,BIOGRAPHY_DATA:BIOGRAPHY_DATA,TIMELINE_DATA:TIMELINE_DATA,MAJOR_MOVEMENTS_DATA:MAJOR_MOVEMENTS_DATA,PRISON_YEARS_DATA:PRISON_YEARS_DATA,HISTORIC_SPEECHES_DATA:HISTORIC_SPEECHES_DATA,GALLERY_DATA:GALLERY_DATA,REFERENCES_DATA:REFERENCES_DATA});